export default function globalSetup() {
  const directory = resolve(process.cwd(), '.tmp');
  mkdirSync(directory, { recursive: true });
  for (const suffix of ['', '-wal', '-shm']) {
    rmSync(resolve(directory, `e2e.sqlite${suffix}`), { force: true });
  }
}

